import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import comp from './main.js';



const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp/In-page Alert',
};

const MESSAGE = 'Callout content. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nam ac nunc neque. Praesent posuere lobortis purus, ac laoreet est volutpat in.';

const infoArgs = { alertType: 'info', title: 'Information alert', message: MESSAGE };
const infoHtml = await squiz.markup(infoArgs);

export const Info = {
  render: (args) => squiz(args),
  args: infoArgs,
  argTypes: {
    alertType: { control: 'select', options: ['info', 'success', 'warning', 'danger'] },
    title: { control: 'text' },
    message: { control: 'text' },
  },
  parameters: {
    docs: {
      description: { story: 'Default alert type -- blue accent and outline, info icon.' },
      source: { code: infoHtml, language: 'html', type: 'code' },
    },
  },
};

const successArgs = { alertType: 'success', title: 'Success alert', message: MESSAGE };
const successHtml = await squiz.markup(successArgs);

export const Success = {
  render: () => squiz(successArgs),
  parameters: {
    docs: {
      description: { story: 'Green accent and outline, check-circle icon.' },
      source: { code: successHtml, language: 'html', type: 'code' },
    },
  },
};

const warningArgs = { alertType: 'warning', title: 'Warning alert', message: MESSAGE };
const warningHtml = await squiz.markup(warningArgs);

export const Warning = {
  render: () => squiz(warningArgs),
  parameters: {
    docs: {
      description: { story: 'Orange accent and outline, warning-triangle icon.' },
      source: { code: warningHtml, language: 'html', type: 'code' },
    },
  },
};

const dangerArgs = { alertType: 'danger', title: 'Danger alert', message: MESSAGE };
const dangerHtml = await squiz.markup(dangerArgs);

export const Danger = {
  render: () => squiz(dangerArgs),
  parameters: {
    docs: {
      description: { story: 'Red accent and outline, cross-circle icon.' },
      source: { code: dangerHtml, language: 'html', type: 'code' },
    },
  },
};
