function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const INFO_SVG = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="1.5"/><line x1="12" y1="11" x2="12" y2="16" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="12" cy="8" r="1" fill="currentColor"/></svg>';
const SUCCESS_SVG = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="1.5"/><path d="M8 12.5l2.5 2.5L16 9.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const WARNING_SVG = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><path d="M12 3.5 21 20H3L12 3.5Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><line x1="12" y1="10" x2="12" y2="14.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="12" cy="17.25" r="1" fill="currentColor"/></svg>';
const DANGER_SVG = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="1.5"/><line x1="9" y1="9" x2="15" y2="15" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><line x1="15" y1="9" x2="9" y2="15" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';

const ICONS_BY_TYPE = {
  info: INFO_SVG,
  success: SUCCESS_SVG,
  warning: WARNING_SVG,
  danger: DANGER_SVG,
};

export default {
  async main(input = {}) {
    const {
      alertType = 'info',
      title = 'Information alert',
      message = 'Callout content. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nam ac nunc neque. Praesent posuere lobortis purus, ac laoreet est volutpat in.',
    } = input;

    const type = ICONS_BY_TYPE[alertType] ? alertType : 'info';

    return /*html*/`
<div class="in-page-alert in-page-alert--${type}">
  <div class="in-page-alert__border"></div>
  <div class="in-page-alert__content">
    <div class="in-page-alert__header">
      <span class="in-page-alert__icon">${ICONS_BY_TYPE[type]}</span>
      <div class="in-page-alert__text">
        <h3 class="in-page-alert__title" data-sq-field="title">${esc(title)}</h3>
        <p class="in-page-alert__message" data-sq-field="message">${esc(message)}</p>
      </div>
    </div>
  </div>
</div>
`;
  },
};
